// ValidateCreateIngressRequestBody runs the validations defined on
// CreateIngressRequestBody
func ValidateCreateIngressRequestBody(body *CreateIngressRequestBody) (err error) {
	if body.Provider == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("provider", "body"))
	}
	if body.Hostname == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("hostname", "body"))
	}
	if body.OauthClientID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("oauth_client_id", "body"))
	}
	if body.OauthClientSecret == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("oauth_client_secret", "body"))
	}
	if body.Provider != nil {
		if !(*body.Provider == "tailscale") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.provider", *body.Provider, []any{"tailscale"}))
		}
	}
	return
}

// ValidateRotateCredentialsRequestBody runs the validations defined on
// RotateCredentialsRequestBody
func ValidateRotateCredentialsRequestBody(body *RotateCredentialsRequestBody) (err error) {
	if body.OauthClientID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("oauth_client_id", "body"))
	}
	if body.OauthClientSecret == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("oauth_client_secret", "body"))
	}
	return
}
